import 'fake-indexeddb/auto';
import {ScopedEditorStore} from '../src/sync/editorStore';
import {applyNativeOperation} from '../src/sync/server';
import {it,expect} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {newId} from '../src/domain/model';
import type {ProjectData} from '../src/domain/types';
import {bootstrapNativeProject,type AtomicSyncRepository,type ServerIdentity} from '../src/sync/server';
import {applyEditorOperation,readEditorImage} from '../src/sync/editor';
import {createSyncOperation,type SyncOperation} from '../src/sync/protocol';
import {assertAck} from '../src/sync/validation';
const root='/tmp/shinariokanri-independent-rb09-af0c2b9/independent',container='shinariokanri-independent-rb09-af0c2b9',owner:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000001',sessionId:'10000000-0000-4000-8000-000000000001'},editor:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000002',sessionId:'10000000-0000-4000-8000-000000000002'},calls:unknown[]=[];
function arg(v:unknown):string{if(v===null)return'null';if(v&&typeof v==='object'&&'rawSQL'in v)return(v as {rawSQL:string}).rawSQL;return"'"+(typeof v==='object'?JSON.stringify(v):String(v)).replace(/'/g,"''")+"'"+(typeof v==='object'?'::jsonb':'');}
function sql(text:string){const r=spawnSync('docker',['exec','-i',container,'psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:text,encoding:'utf8',timeout:20000,maxBuffer:32*1024*1024});calls.push({sql:text,status:r.status,stdout:r.stdout,stderr:r.stderr});writeFileSync(root+'/sql-known-authority-calls.json',JSON.stringify(calls,null,2)+'\n');if(r.status!==0)throw Error(r.stderr||'SQL_CALL_FAILED');return r.stdout;}
function rpc(name:string,values:unknown[]){const out=sql('set role service_role;\nselect public.'+name+'('+values.map(arg).join(',')+')::text;\n').trim();return out?JSON.parse(out):null;}
const repository:AtomicSyncRepository={read:async(i,p,b,o)=>rpc('scenario_sync_engine_context',[i.accountId,i.sessionId,p,b,o]),bootstrap:async(i,v)=>rpc('scenario_sync_bootstrap',[i.accountId,i.sessionId,v.project.projectId,v.project,v.documents,v.worlds]),commit:async(i,v)=>rpc('scenario_sync_commit_prepared',[i.accountId,i.sessionId,v.projectId,v.expectedRevision,v.operation,v.operationHash,v.ack,v.documents,v.image,{rawSQL:'ARRAY['+(v.derivedIds??[]).map(id=>"'"+id+"'").join(',')+']::uuid[]'}])};
function proof(id:string,data:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(data,null,2)+'\n');}
async function seed(){const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string};f.p.projectId=newId();f.p.entities.forEach(e=>e.projectId=f.p.projectId);const a=f.p.entities.find(e=>e.id===f.idA)!;a.customValues['private-editor-canary']='PRIVATE_GRANTED_DOC_FIELD';const b=f.p.entities.find(e=>e.id===f.idB)!;b.visibility='private';b.name='PRIVATE_EDITOR_RECORD_CANARY';await bootstrapNativeProject(repository,owner,{project:f.p,worlds:{}});rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,'editor',null,false,{rawSQL:'array[]::uuid[]'},0]);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']}],1,1]);return f;}
async function rename(f:Awaited<ReturnType<typeof seed>>,name='許可された編集😀'):Promise<SyncOperation>{const image=await readEditorImage(repository,editor,f.p.projectId),base=image.documents[0],local=structuredClone(base);local.fields.name=name;return createSyncOperation({scope:{accountId:editor.accountId,projectId:f.p.projectId},baseRevision:image.serverRevision,operationId:newId(),targets:[{base,local}]});}
it('R9SQL-authority-content actual SQL grant3/read1→ownercontent2→scoped ACK2/grant3 cannot leave revoked B writable or accept the delayed read1 as current A',async()=>{
 const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string};f.p.projectId=newId();f.p.entities.forEach(e=>e.projectId=f.p.projectId);await bootstrapNativeProject(repository,owner,{project:f.p,worlds:{}});rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,'editor',null,false,{rawSQL:'array[]::uuid[]'},0]);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']},{id:f.idB,fields:['name']}],1,1]);const initial=await readEditorImage(repository,editor,f.p.projectId),cache=new ScopedEditorStore(editor.accountId);
 try{
  await cache.receive(initial);await cache.saveField(f.p.projectId,f.idA,'name','SQL端末A');const op=(await cache.prepare(f.p.projectId))!;
  rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']}],1,2]);const delayed=await readEditorImage(repository,editor,f.p.projectId);expect(delayed.authorizationRevision).toBe('3');expect(delayed.serverRevision).toBe('1');expect(delayed.documents.map(d=>d.id)).toEqual([f.idA]);
  const ownerState=await repository.read(owner,f.p.projectId,'1',null),base=ownerState.documents.find(d=>d.id===f.idA)!,local=structuredClone(base);local.fields.name='SQLサーバーA-content2';const ownerOp=await createSyncOperation({scope:{accountId:owner.accountId,projectId:f.p.projectId},baseRevision:'1',operationId:newId(),targets:[{base,local}]});const ownerAck=await applyNativeOperation(repository,owner,ownerOp);expect(ownerAck.serverRevision).toBe('2');
  const ack=await applyEditorOperation(repository,editor,op);expect(ack.status).toBe('conflict');expect(ack.serverRevision).toBe('2');expect(ack.authorizationRevision).toBe('3');expect(ack.confirmedDocuments!.map(d=>d.id)).toEqual([f.idA]);await assertAck(op,ack);await cache.acknowledge(ack);const before=await cache.get(f.p.projectId);let fieldError;try{await cache.saveField(f.p.projectId,f.idB,'name','SQL現行ACKで撤回を知ったB');}catch(e){fieldError=e;}const afterField=await cache.get(f.p.projectId);let receiveError;try{await cache.receive(delayed);}catch(e){receiveError=e;}const afterRead=await cache.get(f.p.projectId);
  proof('R9SQL-authority-content',{initial,delayed,ownerAck,ack,before,afterField,afterRead,fieldError:String(fieldError),receiveError:String(receiveError),environment:'Real network-none PostgreSQL typed owner/editor RPCs and public client store; synthetic Auth/Storage, not live Supabase'});
  expect(fieldError).toMatchObject({code:'FORBIDDEN'});expect(afterField).toEqual(before);expect(receiveError).toMatchObject({code:'REVISION_CHANGED'});expect(afterRead).toEqual(afterField);
 }finally{await cache.delete();}
});
